from pathlib import Path
import base64
import subprocess
import sys

# Exact user-provided black MX logo, downsampled to 256px only for repository size.
# GitHub Actions upscales it losslessly in geometry to 1024px before asset compilation.
ICON_B64 = ""


def main() -> None:
    out = Path(sys.argv[1]).resolve()
    out.parent.mkdir(parents=True, exist_ok=True)
    small = out.with_suffix('.source.png')
    small.write_bytes(base64.b64decode(ICON_B64))
    subprocess.run(['sips', '-z', '1024', '1024', str(small), '--out', str(out)], check=True)
    small.unlink(missing_ok=True)


if __name__ == '__main__':
    main()
